async function snapshot(){const result:Record<string,unknown>={};for(const table of ['source_connections','source_channels','source_items','source_channel_item_links','source_channel_user_subscriptions','source_request_quota_state','scheduler_tasks','extraction_jobs'])result[table]=(await db.pool.query(`SELECT to_jsonb(t) AS row FROM ${table} t ORDER BY to_jsonb(t)::text`)).rows;return result;}
