it('uses canonical persisted messages and a single exact-profile Run under replay, rejecting secrets before storage',async ctx=>{if(!db.available)return ctx.skip();const conversation=new SourceGoalConversation(db.pool,config);const g=await conversation.begin(identity,{search_path:'api',intent:'Follow robotics updates'});await expect(conversation.send(identity,g.id,{content:'api_key=THIS_IS_NOT_A_REAL_KEY_123456789',idempotency_key:'secret'})).rejects.toMatchObject({statusCode:422});const [a,b]=await Promise.all([conversation.send(identity,g.id,{content:'Follow robotics updates',idempotency_key:'one'}),conversation.send(identity,g.id,{content:'Follow robotics updates',idempotency_key:'one'})]);expect(a.run_id).toBe(b.run_id);expect((await db.pool.query('SELECT count(*)::int n FROM messages')).rows[0].n).toBe(1);const run=(await db.pool.query('SELECT * FROM runs WHERE id=$1',[a.run_id])).rows[0];expect(run.model_override_json.chat_turn.session_id).toBe(a.session_id);expect(run.requested_runtime_profile_id).toBe(g.runtime_profile_id);expect((await new SourceGoalService(db.pool,config,port).read(identity,g.id)).messages).toHaveLength(1)});
