it('serializes competing goals on the same source and preserves the original transfer snapshot on a later plan',async ctx=>{
 if(!db.available)return ctx.skip();const a=await prepared();const b=await a.service.create(identity,{intent:'Robotics',agent_id:a.goal.agent_id,runtime_profile_id:a.goal.runtime_profile_id});await db.pool.query('UPDATE runs SET contract_snapshot_json=$2 WHERE id=$1',[author,{workflow_input_json:{source_goal:{goal_id:b.id,purpose:'explore'}}}]);const bv=await a.service.writeVersion(identity,{goal_id:b.id,expected_revision:0,plan:{summary:'Robotics',sources:[{source_connection_id:connectionId,source_channel_id:channelId,reason:'Robotics',supports_history:false,implementation:{kind:'connector'}}],limitations:[]}},author);await a.service.preview(identity,b.id,bv.id,AbortSignal.timeout(10000));const results=await Promise.allSettled([a.service.follow(identity,a.goal.id,{version_id:a.version.id,idempotency_key:'a'}),a.service.follow(identity,b.id,{version_id:bv.id,idempotency_key:'b'})]);expect(results.filter(r=>r.status==='fulfilled')).toHaveLength(1);expect(results.filter(r=>r.status==='rejected')).toHaveLength(1);expect((await db.pool.query(`SELECT count(*)::int n FROM scheduler_tasks WHERE task_type='source_goal_tick' AND status='active'`)).rows[0].n).toBe(1);
 const owner=(await db.pool.query("SELECT * FROM source_goals WHERE active_version_id IS NOT NULL")).rows[0];const first=owner.compatibility_json.transfers[channelId];await db.pool.query('UPDATE runs SET contract_snapshot_json=$2 WHERE id=$1',[author,{workflow_input_json:{source_goal:{goal_id:owner.id,purpose:'explore'}}}]);const next=await a.service.writeVersion(identity,{goal_id:owner.id,expected_revision:owner.revision,plan:{summary:'Refined robotics',sources:[{source_connection_id:connectionId,source_channel_id:channelId,reason:'Robotics',supports_history:false,implementation:{kind:'connector'}}],limitations:[]}},author);await a.service.preview(identity,owner.id,next.id,AbortSignal.timeout(10000));await a.service.follow(identity,owner.id,{version_id:next.id,idempotency_key:'next'});expect((await db.pool.query('SELECT compatibility_json FROM source_goals WHERE id=$1',[owner.id])).rows[0].compatibility_json.transfers[channelId]).toEqual(first);
});
it('recovers a pending message onto an already admitted headless goal Run without another dispatch or budget charge',async ctx=>{
 if(!db.available)return ctx.skip();const conversation=new SourceGoalConversation(db.pool,config);const g=await conversation.begin(identity,{search_path:'api',intent:'Follow robotics'});const {PgSessionRepository}=await import('../src/modules/sessions/repository.js');const sessions=new PgSessionRepository(db.pool);const session=await sessions.createSession(identity.spaceId,identity.userId,{title:'Follow robotics',metadata:{source_goal_id:g.id}});await db.pool.query('UPDATE source_goals SET session_id=$2 WHERE id=$1',[g.id,session.id]);const message=await sessions.addMessage(identity.spaceId,identity.userId,session.id,{role:'user',content:'Follow robotics',metadata:{source_goal_message_key:'interrupted',source_goal_dispatch_pending:true}});const {queueSourceGoalAgent}=await import('../src/modules/sources/goals/agent.js');const admitted=await queueSourceGoalAgent(db.pool,config,identity,g.id,'explore');const resumed=await conversation.send(identity,g.id,{content:'Follow robotics',idempotency_key:'interrupted'});expect(resumed.run_id).toBe(admitted.run_id);expect((await db.pool.query('SELECT session_id FROM runs WHERE id=$1',[resumed.run_id])).rows[0].session_id).toBe(session.id);expect((await db.pool.query('SELECT run_id,metadata_json FROM messages WHERE id=$1',[message!.id])).rows[0]).toMatchObject({run_id:admitted.run_id});expect((await db.pool.query('SELECT agent_attempts FROM source_goals WHERE id=$1',[g.id])).rows[0].agent_attempts).toBe(1);expect((await db.pool.query(`SELECT count(*)::int n FROM jobs WHERE payload_json->>'run_id'=$1`,[admitted.run_id])).rows[0].n).toBe(1);
});
