it('serializes a competing legacy job and scheduler transfer without dual ownership',async ctx=>{
 if(!db.available)return ctx.skip();const {goal,service,version}=await prepared();const holder=await db.pool.connect();await holder.query('BEGIN');await holder.query('SELECT id FROM source_channels WHERE id=$1 FOR UPDATE',[channelId]);
 const start=service.follow(identity,goal.id,{version_id:version.id,idempotency_key:'handover-race'});let insert:Promise<unknown>|undefined;
 try{
  let waiting=false;for(let n=0;n<100&&!waiting;n++){waiting=(await db.pool.query(`SELECT 1 FROM pg_stat_activity WHERE datname=current_database() AND wait_event_type='Lock' AND query LIKE 'SELECT id FROM source_channels%'`)).rows.length>0;if(!waiting)await new Promise(r=>setTimeout(r,10));}expect(waiting).toBe(true);
  insert=db.pool.query(`INSERT INTO extraction_jobs(id,space_id,connection_id,job_type,status,metadata_json,created_at) VALUES($1,$2,$3,'connection_scan','pending',$4,now())`,[randomUUID(),identity.spaceId,connectionId,{source_channel_id:channelId}]);
  // The INSERT may take the connection lock before transfer reaches it.
  // Both serial orders are valid; accepting both mutations is never valid.
  const settled=Promise.allSettled([start,insert]);await holder.query('COMMIT');const [handover,job]=await settled;
  const owner=(await db.pool.query("SELECT compatibility_json->>'scheduler_owner' AS owner FROM source_goals WHERE id=$1",[goal.id])).rows[0].owner;
  const ticks=(await db.pool.query("SELECT count(*)::int n FROM scheduler_tasks WHERE task_type='source_goal_tick' AND task_key=$1 AND status='active'",[goal.id])).rows[0].n;
  if(handover.status==='fulfilled'){expect(job.status).toBe('rejected');if(job.status==='rejected')expect(job.reason).toMatchObject({code:'23514'});expect(owner).toBe('goal');expect(ticks).toBe(1);expect((await db.pool.query('SELECT count(*)::int n FROM extraction_jobs')).rows[0].n).toBe(0);}
  else{expect(handover.reason).toMatchObject({statusCode:409});expect(job.status).toBe('fulfilled');expect(owner).toBe('legacy');expect(ticks).toBe(0);expect((await db.pool.query('SELECT count(*)::int n FROM extraction_jobs')).rows[0].n).toBe(1);}
 }finally{await holder.query('ROLLBACK');holder.release();await Promise.allSettled([start,...(insert?[insert]:[])])}
});
it('does not resume or modify a legacy schedule after its Source access is revoked',async ctx=>{
 if(!db.available)return ctx.skip();const m=await mapLegacyGoal(db.pool,identity,channelId);const service=new SourceGoalService(db.pool,config,port);await service.stop(identity,m.goal.id);await db.pool.query('UPDATE source_connections SET deleted_at=now() WHERE id=$1',[connectionId]);const before=await snapshot();await expect(service.resume(identity,m.goal.id,'legacy')).rejects.toMatchObject({statusCode:404});expect(await snapshot()).toEqual(before);
});
