it('A2: a legacy PATCH waiting behind takeover cannot reactivate the old task',async ctx=>{
 if(!db.available)return ctx.skip();const {goal,service,version}=await prepared();const holder=await db.pool.connect();await holder.query('BEGIN');await holder.query('SELECT id FROM source_channels WHERE id=$1 FOR UPDATE',[channelId]);const holderPid=(await holder.query<{pid:number}>('SELECT pg_backend_pid() pid')).rows[0].pid;const start=service.follow(identity,goal.id,{version_id:version.id,idempotency_key:'patch-race'});let patch:Promise<unknown>|undefined;try{
  // Exact barrier, observed on the holder's own connection (the pool is busy
  // with the two contenders): the takeover's backend is blocked by this holder...
  const blockedBy=async(pid:number)=>{await holder.query('SELECT pg_stat_clear_snapshot()');return (await holder.query<{pid:number;query:string}>("SELECT pid,query FROM pg_stat_activity WHERE datname=current_database() AND $1=ANY(pg_blocking_pids(pid))",[pid])).rows};
  let follower:number|undefined;for(let n=0;n<500&&!follower;n++){follower=(await blockedBy(holderPid)).find(r=>r.query.startsWith('SELECT id FROM source_channels'))?.pid;if(!follower)await new Promise(r=>setTimeout(r,10));}
  expect(follower).toBeDefined();
  patch=new SourceChannelService(db.pool,config).update(identity,channelId,{fetch_frequency:'daily',status:'active'});const refused=expect(patch).rejects.toMatchObject({statusCode:409});
  // ...and the PATCH is queued behind that takeover backend (tuple-lock order), before the holder releases.
  let queued=false;for(let n=0;n<500&&!queued;n++){await holder.query('SELECT pg_stat_clear_snapshot()');queued=(await holder.query<{n:number}>("SELECT count(*)::int n FROM pg_stat_activity WHERE datname=current_database() AND pid<>$1 AND $1=ANY(pg_blocking_pids(pid)) AND query LIKE 'SELECT id FROM source_channels%'",[follower!])).rows[0].n>0;if(!queued)await new Promise(r=>setTimeout(r,10));}
  expect(queued).toBe(true);
  await holder.query('COMMIT');await start;await refused;expect((await db.pool.query("SELECT task_type FROM scheduler_tasks WHERE status='active' AND next_run_at IS NOT NULL")).rows).toEqual([{task_type:'source_goal_tick'}]);}finally{await holder.query('ROLLBACK');holder.release();await Promise.allSettled([start,...(patch?[patch]:[])])}
});
