 expect((await db.pool.query("SELECT count(*)::int n FROM scheduler_tasks WHERE task_type='source_goal_tick' AND task_key=$1",[created.id])).rows[0].n).toBe(0);
 // Explicit resume activates that exact plan through the confirmed follow; one automatic owner.
